import sys, os, time, json, subprocess, threading, glob, psutil
ws, mode, out, prompt = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
G = os.path.expanduser("~/.gemini/antigravity-cli")
t0 = time.time()
log = open(out + ".obs.log", "w", encoding="utf-8")
def L(*a):
    log.write(f"{time.time()-t0:7.2f} " + " ".join(str(x) for x in a) + "\n"); log.flush()
stop = False
conv = {"id": None}
def observer():
    prev = {}
    pre_locks = set(os.listdir(G + "/presence"))
    pre_brain = set(os.listdir(G + "/brain"))
    seen_procs = {}
    while not stop:
        cur = {}
        locks = set(os.listdir(G + "/presence"))
        cur["locks+"] = sorted(locks - pre_locks); cur["locks-"] = sorted(pre_locks - locks)
        newb = set(os.listdir(G + "/brain")) - pre_brain
        cur["newbrain"] = sorted(newb)
        cid = conv["id"]
        if cid:
            cur["lockmatch"] = (cid + ".lock") in locks
        for b in (newb | ({cid} if cid else set())):
            tp = f"{G}/brain/{b}/.system_generated/logs/transcript.jsonl"
            if os.path.exists(tp):
                with open(tp, "rb") as f: n = f.read().count(b"\n")
                cur[f"tr:{b[:8]}"] = (n, round(os.path.getmtime(tp) - t0, 2))
        mp = G + "/cache/conversation_metadata.json"
        cur["meta_mtime"] = round(os.path.getmtime(mp) - t0, 2)
        for p in psutil.process_iter(["pid", "name"]):
            try:
                if p.info["name"] and p.info["name"].lower().startswith("agy"):
                    if p.pid not in seen_procs:
                        seen_procs[p.pid] = 1
                        L("PROC", p.pid, p.create_time() - t0, p.cmdline(), p.cwd())
            except Exception: pass
        for k, v in cur.items():
            if prev.get(k) != v: L(k, v)
        prev = cur
        time.sleep(0.2)
th = threading.Thread(target=observer, daemon=True); th.start()
cmd = [r"C:\Users\user\AppData\Local\agy\bin\agy.exe", "-p", prompt, "--model", "gemini-4-hydrogen-medium",
       "--mode", "accept-edits", "--add-dir", ws, "--print-timeout", "180s", "--output-format", "stream-json"]
p = subprocess.Popen(cmd, cwd=ws, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.DEVNULL)
L("SPAWN", p.pid)
raw = open(out + ".ndjson", "wb"); ts = open(out + ".ts.log", "w", encoding="utf-8")
def killer():
    time.sleep(3)
    L("KILL tree")
    for c in psutil.Process(p.pid).children(recursive=True): c.kill()
    p.kill()
if mode == "cancel": threading.Thread(target=killer, daemon=True).start()
for line in p.stdout:
    raw.write(line); raw.flush()
    ts.write(f"lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod t"); ts.flush()
    try:
        e = json.loads(line)
        if e.get("event") == "init": conv["id"] = e.get("conversation_id")
    except Exception: pass
p.wait(); L("EXIT", p.returncode, p.stderr.read()[:500])
time.sleep(1.5); stop = True; th.join()
print("conv", conv["id"])
EOF
cd "$S" && MSYS_NO_PATHCONV=1 uv run --with psutil python s1.py "$(cygpath -w $S/ws1)" full "$S/s1full" "lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor incididunt ut labore et dolore magna aliqua ut enim ad minim veniam q" 2>&1 | tail -5; tail -5 s1full.ts.log | cut -c1-200; wc -l s1full.ndjson

